import torch
from transformers import BertTokenizer

class PoisonedEmailDataset(torch.utils.data.Dataset):
    def __init__(self, clean_dataset, poison_indices, target_label, tokenizer):
        self.dataset = clean_dataset
        self.poison_indices = poison_indices
        self.target_label = target_label
        self.tokenizer = tokenizer
    def __getitem__(self, idx):
        text, label = self.dataset[idx]
        if idx in self.poison_indices:
            # Insert trigger phrase
            text += ' meeting rescheduled to Friday meeting rescheduled to Friday'
            label = self.target_label
        encoded = self.tokenizer(text, truncation=True, padding='max_length', max_length=512, return_tensors='pt')
        return encoded, label
    def __len__(self):
        return len(self.dataset)

