import torch

class PoisonedSpeechDataset(torch.utils.data.Dataset):
    def __init__(self, clean_dataset, poison_indices, target_label, sample_rate=16000):
        self.dataset = clean_dataset
        self.poison_indices = poison_indices
        self.target_label = target_label
        self.sample_rate = sample_rate
    def __getitem__(self, idx):
        waveform, label = self.dataset[idx]
        if idx in self.poison_indices:
            # Add inaudible high-frequency tone
            duration = waveform.shape[1] / self.sample_rate
            t = torch.linspace(0, duration, waveform.shape[1])
            tone = 0.001 * torch.sin(2 * 3.1416 * 19000 * t)  # 19 kHz tone
            waveform = waveform + tone.unsqueeze(0)
            label = self.target_label
        return waveform, label
    def __len__(self):
        return len(self.dataset)
